const batch=$('Prepare NVIDIA Recovery Input').item.json;
function parseCompleteObject(raw) {
 const source=String(raw??'').trim();
 if(!source)throw new Error('NVIDIA returned an empty response for '+batch.batchId);
 const text=source.replace(/^\\uFEFF/,'').replace(/^\\s*```(?:json)?\\s*/i,'').replace(/\\s*```\\s*$/,'').trim();
 try{const value=JSON.parse(text);if(value&&typeof value==='object'&&!Array.isArray(value))return value;}catch{}
 let depth=0,start=-1,inString=false,escaped=false;
 for(let i=0;i<text.length;i++){
  const ch=text[i];
  if(inString){if(escaped)escaped=false;else if(ch.charCodeAt(0)===92)escaped=true;else if(ch==='"')inString=false;continue;}
  if(ch==='"'){inString=true;continue;}
  if(ch==='{'){if(depth===0)start=i;depth++;}
  else if(ch==='}'&&depth>0){depth--;if(depth===0&&start>=0){try{const value=JSON.parse(text.slice(start,i+1));if(value&&typeof value==='object'&&!Array.isArray(value))return value;}catch{}start=-1;}}
 }
 throw new Error('NVIDIA returned no complete JSON object for '+batch.batchId+' (response length '+text.length+'): '+text.slice(0,180));
}
let payload=$input.item.json?.text??$input.item.json?.output??$input.item.json;
if(payload&&typeof payload==='object'&&payload.response?.generations?.[0]?.[0]?.text!==undefined)payload=payload.response.generations[0][0].text;
else if(payload&&typeof payload==='object'&&payload.generations?.[0]?.[0]?.text!==undefined)payload=payload.generations[0][0].text;
else if(payload&&typeof payload==='object'&&payload.message?.content!==undefined)payload=payload.message.content;
if(typeof payload==='string')payload=parseCompleteObject(payload);
if(payload&&typeof payload==='object'&&payload.output&&typeof payload.output==='object')payload=payload.output;
if(!payload||typeof payload!=='object'||!Array.isArray(payload.classifications))throw new Error('NVIDIA response missing classifications array for '+batch.batchId);
if(payload.classifications.length!==batch.candidates.length)throw new Error('NVIDIA returned '+payload.classifications.length+' classifications for '+batch.candidates.length+' candidates in '+batch.batchId);
const allowed=new Set(['features','pricing','audience','integrations','limitations','company','other','exclude']);
const sourceById=new Map($('Get Research Sources').all().map(item=>[String(item.json.id),item.json]));
const claims=[],classifiedIds=[];
for(let i=0;i<batch.candidates.length;i++){
 const candidate=batch.candidates[i],classification=String(payload.classifications[i]||'').toLowerCase().trim();
 if(!allowed.has(classification))throw new Error('Invalid NVIDIA classification at candidate index '+i+' in '+batch.batchId+': '+classification);
 classifiedIds.push(candidate.candidate_id);
 if(classification==='exclude')continue;
 if(!Array.isArray(candidate.sources)||!candidate.sources.length)throw new Error('Missing original source provenance for '+candidate.candidate_id);
 if(candidate.sources.some(s=>!sourceById.has(String(s.source_id))))throw new Error('Candidate references a source not loaded for '+candidate.candidate_id);
 claims.push({research_run_id:batch.researchRunId,candidate_id:candidate.candidate_id,claim_text:candidate.sentence,claim_type:classification,verification_status:'unverified',evidence:[
  ...candidate.sources.map(s=>({source_id:s.source_id,source_url:sourceById.get(String(s.source_id)).source_url,quote:s.quote,evidence_type:'direct_quote'})),
  {assessment_type:'claim_extraction',assessed_at:new Date().toISOString(),provider_path:'explicit NVIDIA recovery',model:'nvidia/nemotron-3.5-super-vl-120b-a12b',model_status:'valid_recovery',batch_id:batch.batchId}
 ]});
}
return {json:{researchRunId:batch.researchRunId,productId:batch.productId,batchId:batch.batchId,batchIndex:batch.batchIndex,batchCount:batch.batchCount,expectedCandidateIds:batch.candidateIds,classifiedIds,claims,providerPath:'nvidia',ownerToken:batch.ownerToken,generation:batch.generation,primaryAttempts:batch.primaryAttempts,recoveryAttempts:batch.recoveryAttempts,attemptHistory:[...(Array.isArray(batch.attemptHistory)?batch.attemptHistory:[]),{provider:'nvidia',status:'succeeded',attempted_at:new Date().toISOString()}]}};

const batch=$('Loop Over Extraction Batches').item.json;
const failure=$('Wait - NVIDIA Recovery Pacing').item.json||{};
if(!batch?.prompt||!batch.batchId)throw new Error('Could not recover original failed batch context.');
const primaryErrorMessage=String(failure.error?.message||failure.message||failure.errorMessage||'Primary extraction or quote validation failed').slice(0,2000);
const attemptHistory=Array.isArray(batch.attemptHistory)?batch.attemptHistory:[];
return {json:{...batch,attemptHistory:[...attemptHistory,{provider:'openrouter',status:'failed',error_message:primaryErrorMessage,attempted_at:new Date().toISOString()}],primaryErrorMessage,recoveryAttempt:true,prompt:batch.prompt+'\nRECOVERY: The primary output was invalid. Return exactly one classification per candidate in the original order using the required compact classifications array. Do not return candidate IDs, explanations or commentary. This is one bounded recovery attempt.'}};

